script:
if not doc.institute:
    frappe.throw("Student is missing Institute (Company) information.")
if not doc.admission_no:
    frappe.throw("Student is missing Admission Number.")

company = frappe.get_doc("Company", doc.institute)

if company.custom_tcr_accounts:

    # --- Fees ---
    if company.custom_fees_account:
        if not doc.fees:
            doc.fees = sum(
                entry.debit - entry.credit
                for entry in frappe.get_all(
                    "GL Entry",
                    filters={
                        "party_type": "Customer",
                        "party": doc.admission_no,
                        "account": company.custom_fees_account,
                        "company": doc.institute
                    },
                    fields=["debit", "credit"]
                )
            )
    else:
        frappe.throw("Account not set in Company for 'Fees'.")

    # --- Caution Deposit ---
    if company.custom_caution_deposit_account:
        if not doc.caution_deposit:
            doc.caution_deposit = sum(
                entry.debit - entry.credit
                for entry in frappe.get_all(
                    "GL Entry",
                    filters={
                        "party_type": "Customer",
                        "party": doc.admission_no,
                        "account": company.custom_caution_deposit_account,
                        "company": doc.institute
                    },
                    fields=["debit", "credit"]
                )
            )
    else:
        frappe.throw("Account not set in Company for 'Caution Deposit'.")

    # --- Advance Annual Fees ---
    if company.custom_advance_annual_fees_account:
        if not doc.advance_annual_fees:
            doc.advance_annual_fees = sum(
                entry.debit - entry.credit
                for entry in frappe.get_all(
                    "GL Entry",
                    filters={
                        "party_type": "Customer",
                        "party": doc.admission_no,
                        "account": company.custom_advance_annual_fees_account,
                        "company": doc.institute
                    },
                    fields=["debit", "credit"]
                )
            )
    else:
        frappe.throw("Account not set in Company for 'Advance Annual Fees'.")

    # --- Excess Fees Paid ---
    if company.custom_excess_fees_paid_account:
        if not doc.excess_fees_paid:
            doc.excess_fees_paid = sum(
                entry.debit - entry.credit
                for entry in frappe.get_all(
                    "GL Entry",
                    filters={
                        "party_type": "Customer",
                        "party": doc.admission_no,
                        "account": company.custom_excess_fees_paid_account,
                        "company": doc.institute
                    },
                    fields=["debit", "credit"]
                )
            )
    else:
        frappe.throw("Account not set in Company for 'Excess Fees Paid'.")

    # --- Others ---
    if company.custom_other_account:
        if not doc.others:
            doc.others = sum(
                entry.debit - entry.credit
                for entry in frappe.get_all(
                    "GL Entry",
                    filters={
                        "party_type": "Customer",
                        "party": doc.admission_no,
                        "account": company.custom_other_account,
                        "company": doc.institute
                    },
                    fields=["debit", "credit"]
                )
            )

    # --- Net Total ---
    creditor_total = (doc.fees or 0) + (doc.others or 0)
    debtor_total = (doc.caution_deposit or 0) + (doc.advance_annual_fees or 0) + (doc.excess_fees_paid or 0)
    doc.net_total = creditor_total + debtor_total




if doc.seat_retained and doc.expected_date_of_leaving and doc.institute:
    # Fetch the Company using the institute field
    company_doc = frappe.get_doc("Company", doc.institute)
    retain_years = int(company_doc.custom_seat_retaining_policy or 0)

    if retain_years > 0:
        retain_upto_date = frappe.utils.add_years(doc.expected_date_of_leaving, retain_years)
        doc.custom_seat_retain_upto = retain_upto_date
        frappe.msgprint(f"Seat will be retained until {frappe.format_date(retain_upto_date)}")
    else:
        doc.custom_seat_retain_upto = None
        frappe.msgprint("Seat retaining policy is not set in the Company master.")
else:
    doc.custom_seat_retain_upto = None
